<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> BoolOption options </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Args.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">parse</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(BooleanOption.class, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-l&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
